window.ScripturaLexicons.BDAG_PART_0149 = {"source":"BDAG","searchAnchorId":"bdag-search-anchor","entryAnchorId":"bdag-entry-anchor","rowsHtml":"<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-heteroglossos-bdag\" data-source=\"BDAG\" data-search=\"ἑτερόγλωσσος, ον heteróglōssos adjetivo que fala língua estrangeira BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἑτερόγλωσσος, ον</td><td>adjetivo</td><td>que fala língua estrangeira</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-heterognomoneo-bdag\" data-source=\"BDAG\" data-search=\"ἑτερογνωμονέω heterognōmonéō verbo discordar; ter opinião diferente BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἑτερογνωμονέω</td><td>verbo</td><td>discordar; ter opinião diferente</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-heterognomon-bdag\" data-source=\"BDAG\" data-search=\"ἑτερογνώμων, ον, heterognṓmōn adjetivo de opinião diferente BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἑτερογνώμων, ον,</td><td>adjetivo</td><td>de opinião diferente</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-heterodidaskaleo-bdag\" data-source=\"BDAG\" data-search=\"ἑτεροδιδασκαλέω heterodidaskaléō verbo ensinar doutrina divergente BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἑτεροδιδασκαλέω</td><td>verbo</td><td>ensinar doutrina divergente</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-heterodoxeo-bdag\" data-source=\"BDAG\" data-search=\"ἑτεροδοξέω heterodoxéō verbo sustentar opiniões divergentes BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἑτεροδοξέω</td><td>verbo</td><td>sustentar opiniões divergentes</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-heterodoxia-bdag\" data-source=\"BDAG\" data-search=\"ἑτεροδοξία, ας, ἡ heterodoxía substantivo feminino opinião estranha ou errônea BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἑτεροδοξία, ας, ἡ</td><td>substantivo feminino</td><td>opinião estranha ou errônea</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-heterozygeo-bdag\" data-source=\"BDAG\" data-search=\"ἑτεροζυγέω heterozygéō verbo estar em jugo desigual BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἑτεροζυγέω</td><td>verbo</td><td>estar em jugo desigual</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-heteroklines-bdag\" data-source=\"BDAG\" data-search=\"ἑτεροκλινής, ές, heteroklinḗs adjetivo inclinado; de outra lealdade BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἑτεροκλινής, ές,</td><td>adjetivo</td><td>inclinado; de outra lealdade</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-heteros-bdag\" data-source=\"BDAG\" data-search=\"ἕτερος, α, ον héteros adjetivo e substantivo outro; diferente; próximo BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἕτερος, α, ον</td><td>adjetivo e substantivo</td><td>outro; diferente; próximo</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-heteros-adv-bdag\" data-source=\"BDAG\" data-search=\"ἑτέρως hetérōs advérbio diferentemente; de outro modo BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἑτέρως</td><td>advérbio</td><td>diferentemente; de outro modo</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-eti-bdag\" data-source=\"BDAG\" data-search=\"ἔτι éti advérbio ainda; já não; além disso BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἔτι</td><td>advérbio</td><td>ainda; já não; além disso</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-hetoimazo-bdag\" data-source=\"BDAG\" data-search=\"ἑτοιμάζω hetoimázō verbo preparar; deixar pronto BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἑτοιμάζω</td><td>verbo</td><td>preparar; deixar pronto</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-hetoimas-bdag\" data-source=\"BDAG\" data-search=\"Ἕτοιμας Hétoimas nome próprio remissão a Ἐλύμας BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Ἕτοιμας</td><td>nome próprio</td><td>remissão a Ἐλύμας</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-hetoimasia-bdag\" data-source=\"BDAG\" data-search=\"ἑτοιμασία, ας, ἡ hetoimasía substantivo feminino preparação; prontidão BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἑτοιμασία, ας, ἡ</td><td>substantivo feminino</td><td>preparação; prontidão</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-hetoimos-bdag\" data-source=\"BDAG\" data-search=\"ἕτοιμος, η, ον hétoimos adjetivo pronto; preparado; disposto BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἕτοιμος, η, ον</td><td>adjetivo</td><td>pronto; preparado; disposto</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-hetoimos-adv-bdag\" data-source=\"BDAG\" data-search=\"ἑτοίμως hetoímōs advérbio prontamente; de boa vontade BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἑτοίμως</td><td>advérbio</td><td>prontamente; de boa vontade</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-etos-bdag\" data-source=\"BDAG\" data-search=\"ἔτος, ους, τό étos substantivo neutro ano; período de um ano BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἔτος, ους, τό</td><td>substantivo neutro</td><td>ano; período de um ano</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-eu-bdag\" data-source=\"BDAG\" data-search=\"εὖ eû advérbio e interjeição bem; corretamente; muito bem! BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">εὖ</td><td>advérbio e interjeição</td><td>bem; corretamente; muito bem!</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-eua-bdag\" data-source=\"BDAG\" data-search=\"Εὕα, ας, ἡ Heúa nome próprio feminino Eva BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Εὕα, ας, ἡ</td><td>nome próprio feminino</td><td>Eva</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-euangelizo-bdag\" data-source=\"BDAG\" data-search=\"εὐαγγελίζω euangelízō verbo anunciar boas notícias; proclamar o evangelho BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">εὐαγγελίζω</td><td>verbo</td><td>anunciar boas notícias; proclamar o evangelho</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n","cardsHtml":"<article id=\"entry-heteroglossos-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἑτερόγλωσσος, ον</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦heteróglōssos⟧</span><span class=\"separator\">·</span><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">Ver <span class=\"greek\">ἕτερος</span> e <span class=\"greek\">γλῶσσα</span>. Atestações: Políbio 23, 13, 2; Estrabão 8, 1, 2; Fílon, Conf. Lingu. 8; Áquila, Sl 113:1 e Is 33:19. <strong>Que fala uma língua estrangeira</strong>. A construção <span class=\"greek\">ἐν</span> <span class=\"greek\">ἑτερογλώσσοις</span> <span class=\"greek\">λαλεῖν</span> significa «falar por meio de pessoas que empregam línguas estranhas» (<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.14.21\" target=\"_blank\" rel=\"noopener noreferrer\">1Co 14:21</a>), segundo Is 28:11, passagem em que Áquila parece ter escrito <span class=\"greek\">ἑτερόγλ</span>. Paulo interpreta a expressão como referente ao falar em línguas. Bibliografia: M-M; TW.</p></section></article>\n<article id=\"entry-heterognomoneo-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἑτερογνωμονέω</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦heterognōmonéō⟧</span><span class=\"separator\">·</span><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">Ver <span class=\"greek\">ἕτερος</span>, <span class=\"greek\">γνώμη</span> e o verbete seguinte. Atestado em Cirilo de Alexandria; cf. Lampe, s.v. <strong>Ter opinião diferente; não estar de acordo com</strong>. <span class=\"greek\">ἐδόκει</span> <span class=\"greek\">γ</span>[<span class=\"greek\">ὰρ</span> <span class=\"greek\">ἑτε</span>]|<span class=\"greek\">ρογνωμονεῖν</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">ἐκ</span>[<span class=\"greek\">ε</span>]<span class=\"greek\">ίν</span>[<span class=\"greek\">ου</span> <span class=\"greek\">ἐν</span>]|<span class=\"greek\">νοίᾳ</span>: «pois as palavras [de Maria Madalena] não pareciam estar de acordo com a maneira de pensar [de Cristo]», GMary 463, 9–11. Bibliografia: DELG, s.v. <span class=\"greek\">γιγνώσκω</span>.</p></section></article>\n<article id=\"entry-heterognomon-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἑτερογνώμων, ον,</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦heterognṓmōn⟧</span><span class=\"separator\">·</span><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">Genitivo <span class=\"greek\">ονος</span>. Ver o verbete precedente; Vettius Valens 79, 18; Agátias 4, 2; cf. <span class=\"greek\">ἑτερογνωμοσύνη</span> em Josefo, Ant. 10, 281. <strong>Que tem opinião diferente</strong>. <span class=\"greek\">γυναικὸς</span> <span class=\"greek\">ἑτερογνώμονος</span> <span class=\"greek\">ὑπαρχούσης</span>: «sendo a mulher [a esposa de Ló] de opinião diferente», 1Cl 11:2. Bibliografia: M-M, s.v. <span class=\"greek\">ἑτερόγλωσσος</span>.</p></section></article>\n<article id=\"entry-heterodidaskaleo-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἑτεροδιδασκαλέω</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦heterodidaskaléō⟧</span><span class=\"separator\">·</span><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">Ver <span class=\"greek\">ἕτερος</span> e <span class=\"greek\">διδασκαλία</span>; vocábulo encontrado somente em escritores cristãos. <strong>Ensinar em oposição à instrução normativa; transmitir um ensino divergente, isto é, divisivo</strong>: <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.1.3\" target=\"_blank\" rel=\"noopener noreferrer\">1Tm 1:3</a>; 6:3; cf. 1QH 4, 16; Inácio, IPol 3:1. Bibliografia: DELG, s.v. <span class=\"greek\">διδάσκω</span>; TW.</p></section></article>\n<article id=\"entry-heterodoxeo-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἑτεροδοξέω</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦heterodoxéō⟧</span><span class=\"separator\">·</span><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">Ver <span class=\"greek\">ἕτερος</span>, <span class=\"greek\">δοκέω</span> e o verbete seguinte. Paralelos: Platão, Theaet. 190e; Fílon, Rer. Div. Her. 247. Josefo, Bell. 2, 129, usa <span class=\"greek\">ἑτερόδοξος</span> a respeito dos que não pertencem aos essênios. <strong>Sustentar opiniões diferentes, isto é, divisivas ou sectárias</strong>: ISm 6:2. Bibliografia: TW.</p></section></article>\n<article id=\"entry-heterodoxia-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἑτεροδοξία, ας, ἡ</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦heterodoxía⟧</span><span class=\"separator\">·</span><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">Genitivo <span class=\"greek\">ας</span>. Ver o verbete precedente; Platão, Theaet. 193d; Fílon, Fgm. 72 Harris. <strong>Expressão de pensamento divergente de opiniões ou ensinamentos aceitos, com implicação de divisão; opinião estranha ou errônea</strong>: IMg 8:1. Bibliografia: TW.</p></section></article>\n<article id=\"entry-heterozygeo-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἑτεροζυγέω</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦heterozygéō⟧</span><span class=\"separator\">·</span><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">Ver <span class=\"greek\">ἕτερος</span> e <span class=\"greek\">ζυγός</span>. <span class=\"greek\">κτήνη</span> <span class=\"greek\">ἑτερόζυγα</span> designa «animais de tração que exigem tipos diferentes de jugo porque são de espécies distintas», por exemplo, boi e jumento: Lv 19:19; Fílon, Spec. Leg. 4, 203; cf. Josefo, Ant. 4, 228. O adjetivo <span class=\"greek\">ἑτερόζυγος</span> aparece com sentido diferente em Ps.-Phoc. 15 e, já em PCairZen 38, 11 [257 a.C.], em geral significa «que não pertence ao mesmo conjunto». <strong>Estar unido por jugo desigual; formar par incompatível</strong>, com <span class=\"greek\">τινί</span> «com alguém»: <span class=\"greek\">μὴ</span> <span class=\"greek\">γίνεσθε</span> <span class=\"greek\">ἑτεροζυγοῦντες</span> <span class=\"greek\">ἀπίστοις</span>, «não vos ponhais em jugo desigual com incrédulos», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.6.14\" target=\"_blank\" rel=\"noopener noreferrer\">2Co 6:14</a>. J. Fitzmyer, «Qumran and 2 Cor 6:14–7:1», CBQ 23 (1961), 271–80, relaciona a imagem do jugo à instrução; cf. Straub 6. Bibliografia: DELG, s.v. <span class=\"greek\">ζεύγνυμι</span>; M-M; TW; Spicq.</p></section></article>\n<article id=\"entry-heteroklines-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἑτεροκλινής, ές,</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦heteroklinḗs⟧</span><span class=\"separator\">·</span><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">Genitivo <span class=\"greek\">οῦς</span>. Ver <span class=\"greek\">ἕτερος</span> e <span class=\"greek\">κλινέω</span> («inclinar-se»), Hipócrates e outros. <strong>No sentido geral, inclinado para fora da vertical</strong>, como edifícios «inclinados para um lado»; por transferência ao campo mental, <strong>inclinado a; propenso a</strong>; cf. Epicteto 3, 12, 7: <span class=\"greek\">ἑτεροκλινῶς</span> <span class=\"greek\">ἔχω</span> <span class=\"greek\">πρὸς</span> <span class=\"greek\">ἡδονήν</span>; o advérbio também em 1Cr 12:34. No uso documentado: <strong>que presta lealdade a outra parte</strong>, a respeito de rebeldes ou apóstatas, 1Cl 11:1; 47:7. Bibliografia: DELG, s.v. <span class=\"greek\">κλίνω</span>.</p></section></article>\n<article id=\"entry-heteros-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἕτερος, α, ον</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦héteros⟧</span><span class=\"separator\">·</span><span>adjetivo e substantivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\"><span class=\"greek\">ἕτερος</span>, <span class=\"greek\">α</span>, <span class=\"greek\">ον</span>. Atestado desde Homero. No NT não ocorre em 1–2Pedro, 1–3João nem Apocalipse; em Marcos ocorre somente no final entre colchetes (16:12), e em João somente em 19:37. Como adjetivo e substantivo, em geral significa «outro».</p><p class=\"entry-text\">① <strong>Que se distingue de outro elemento expresso ou pressuposto: outro.</strong></p><p class=\"entry-text\">ⓐ <strong>O outro de dois</strong>: contrapõe uma pessoa ou coisa determinada a outra. Apiano, Hann. 43 §185, <span class=\"greek\">Ἄννων</span> <span class=\"greek\">ἕτερος</span>, «o outro dos dois Hanões»; acerca de um olho, ApcEsdr 4:29; Atenágoras 17, 4; cf. <span class=\"greek\">θάτερος</span> em Justino, D. 1, 2 e outros; Taciano 8, 1 e outros. <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">ἑτέρῳ</span> <span class=\"greek\">πλοίῳ</span>, «no outro barco» (<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.5.7\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 5:7</a>; cf. 23:40). <span class=\"greek\">ὁ</span> <span class=\"greek\">ἕ</span>. em contraste com <span class=\"greek\">ὁ</span> <span class=\"greek\">πρῶτος</span> (Xenofonte, An. 3, 4, 25): <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.21.30\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 21:30</a>; <span class=\"greek\">ὁ</span> <span class=\"greek\">εἷς</span> … <span class=\"greek\">ὁ</span> <span class=\"greek\">ἕ</span>. («um … o outro»; ver <span class=\"greek\">εἷς</span> 5d): <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.6.24\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 6:24</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.7.41\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 7:41</a>; 16:13; 17:34s.; 18:10; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.23.6\" target=\"_blank\" rel=\"noopener noreferrer\">At 23:6</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.4.6\" target=\"_blank\" rel=\"noopener noreferrer\">1Co 4:6</a>. <span class=\"greek\">ἕ</span>. <span class=\"greek\">βασιλεύς</span>, «outro rei» (dos dois mencionados), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.14.31\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 14:31</a>. O emprego em Hv 3, 8, 4 é coloquial: mencionam-se sete mulheres, mas o narrador descreve as duas primeiras e antecipa a pergunta de Hermas sobre as outras cinco; por isso, trata as duas primeiras como série completa. Também 1Cl 38:2.</p><p class=\"entry-text\">ⓑ <strong>Entre mais de dois.</strong> <span class=\"greek\">α</span>. «Outro»: <span class=\"greek\">ἕ</span>. <span class=\"greek\">τῶν</span> <span class=\"greek\">μαθητῶν</span>, «outro dos discípulos», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.8.21\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 8:21</a>; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.1.19\" target=\"_blank\" rel=\"noopener noreferrer\">Gl 1:19</a>. <span class=\"greek\">ἕ</span>. <span class=\"greek\">προσδοκῶμεν</span>;, «devemos esperar outra pessoa?», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.11.3\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 11:3</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.7.19\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 7:19</a>, variante de leitura. <span class=\"greek\">ἐν</span> <span class=\"greek\">ἑ</span>. <span class=\"greek\">σαββάτῳ</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.6.6\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 6:6</a>. <span class=\"greek\">ἑτέρα</span> <span class=\"greek\">γραφή</span>, «outra passagem das Escrituras», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.19.37\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 19:37</a>; 2Cl 2:4; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.9.56\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 9:56</a>, 59, 61; 16:18 (cf. Jó 31:10); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.1.20\" target=\"_blank\" rel=\"noopener noreferrer\">At 1:20</a> (Sl 108:8); 7:18 (Êx 1:8); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.7.3\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 7:3</a>. <span class=\"greek\">ἕτερον</span> <span class=\"greek\">παράδοξον</span>, «outro prodígio», Papias (2:9). <span class=\"greek\">ἕ</span>. <span class=\"greek\">τις</span>, «outra pessoa, qualquer outra», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.8.34\" target=\"_blank\" rel=\"noopener noreferrer\">At 8:34</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.8.39\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 8:39</a>; 13:9 (cf. Cícero, Tusc. 4, 7, 16); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.1.10\" target=\"_blank\" rel=\"noopener noreferrer\">1Tm 1:10</a>; <span class=\"greek\">ἤ</span> <span class=\"greek\">τις</span> <span class=\"greek\">ἕ</span>., Papias (2:4); cf. <span class=\"greek\">οὐδεὶς</span> <span class=\"greek\">ἕ</span>., En 24:4; Justino, D. 49, 3.</p><p class=\"entry-text\">ⓑ <span class=\"greek\">β</span>. Também no plural <span class=\"greek\">ἕτεροι</span>, «outros»: <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.2.13\" target=\"_blank\" rel=\"noopener noreferrer\">At 2:13</a> (<span class=\"greek\">ἕτεροι</span> <span class=\"greek\">δέ</span> acrescenta à opinião anteriormente apresentada a opinião de outras pessoas, como no escólio a Píndaro, P. 9, 183), 40; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.10.1\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 10:1</a>. <span class=\"greek\">ἕτεραι</span> <span class=\"greek\">γενεαί</span>, «outras gerações» (cf. Sl 47:14; 77:4, 6 e outros), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.3.5\" target=\"_blank\" rel=\"noopener noreferrer\">Ef 3:5</a>. <span class=\"greek\">ἑτέρους</span> <span class=\"greek\">διδάσκειν</span>, «ensinar outros» (Dn 11:4), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.2.2\" target=\"_blank\" rel=\"noopener noreferrer\">2Tm 2:2</a>. No final de enumerações, <span class=\"greek\">ἕτεροι</span> <span class=\"greek\">πολλοί</span>, «muitos outros» (cf. Demóstenes 18, 208, 219; 19, 297; Apiano, Bell. Civ. 2, 62 §260): <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.15.30\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 15:30</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.15.35\" target=\"_blank\" rel=\"noopener noreferrer\">At 15:35</a>; <span class=\"greek\">ἕ</span>. <span class=\"greek\">πολλαί</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.8.3\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 8:3</a>; <span class=\"greek\">ἕ</span>. <span class=\"greek\">πολλά</span> (TestSol 8:9; Josefo, Vi. 39; 261), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.22.65\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 22:65</a>. <span class=\"greek\">πολλὰ</span> <span class=\"greek\">κ</span>. <span class=\"greek\">ἕτερα</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.3.18\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 3:18</a>. <span class=\"greek\">περὶ</span> <span class=\"greek\">ἑτέρων</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.19.39\" target=\"_blank\" rel=\"noopener noreferrer\">At 19:39</a>, variante de leitura. <span class=\"greek\">τινὲς</span> <span class=\"greek\">ἕ</span>. (Josefo, Vi. 15; Ar. 10, 7 <span class=\"greek\">ἕτέρων</span> <span class=\"greek\">τινῶν</span>), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.27.1\" target=\"_blank\" rel=\"noopener noreferrer\">At 27:1</a>. <span class=\"greek\">ἑπτὰ</span> <span class=\"greek\">ἕ</span>. <span class=\"greek\">πνεύματα</span>: o espírito maligno leva consigo «outros sete espíritos malignos», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.12.45\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 12:45</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.11.26\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 11:26</a>; cf. TestSol 15:1 <span class=\"greek\">ἑτέρας</span> <span class=\"greek\">δύο</span> <span class=\"greek\">κεφαλάς</span>; TestAbr B 10, p. 114, 24 [Stone p. 76] <span class=\"greek\">τῶν</span> <span class=\"greek\">ἑτέρων</span> <span class=\"greek\">δύο</span> <span class=\"greek\">στεφανῶν</span>. Para indicar diferença de espécie, <span class=\"greek\">καὶ</span> <span class=\"greek\">ἕ</span>. (<span class=\"greek\">ἑταῖροι</span> em P75; ver <span class=\"greek\">ἑταῖρος</span>) <span class=\"greek\">κακοῦργοι</span> <span class=\"greek\">δύο</span>, «também outros dois, que eram malfeitores», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.23.32\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 23:32</a>; cf. TestJud 9:6; PTebt 41, 9 [c. 119 a.C.] <span class=\"greek\">τινῶν</span> <span class=\"greek\">ἡμῶν</span> [homens] <span class=\"greek\">καὶ</span> <span class=\"greek\">ἑτέρων</span> <span class=\"greek\">γυναικῶν</span>; Dião Crisóstomo 30 [47], 24 <span class=\"greek\">ἑτέραν</span> <span class=\"greek\">γυναῖκα</span> <span class=\"greek\">Σεμίρ</span>., «e, além disso, uma mulher, Semíramis». <span class=\"greek\">οἱ</span> <span class=\"greek\">ἕ</span>., «os outros, os restantes», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.11.16\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 11:16</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.4.43\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 4:43</a>.</p><p class=\"entry-text\">ⓑ <span class=\"greek\">γ</span>. Emprega-se de modo intercambiável com <span class=\"greek\">ἄλλος</span>, sentido como equivalente: Ps.-Platão, Alcib. I 116e; Apolônio de Rodes 4, 141; Dião Crisóstomo 57 [74], 22; Arriano, Anab. 5, 21, 2–3; Herm. Wr. 11, 12a; CPR I, 103, 21 <span class=\"greek\">ἀπό</span> <span class=\"greek\">τε</span> <span class=\"greek\">ἄλλων</span> <span class=\"greek\">πρασέων</span> <span class=\"greek\">ἢ</span> <span class=\"greek\">ἑτέρων</span> <span class=\"greek\">οἰκονομιῶν</span>; 3, 19; 6, 17; compare-se POxy 276, 11 <span class=\"greek\">σὺν</span> <span class=\"greek\">ἄλλοις</span> <span class=\"greek\">σιτολόγοις</span> com PGen 36, 10 <span class=\"greek\">σὺν</span> <span class=\"greek\">ἑτέροις</span> <span class=\"greek\">ἱερεῦσι</span>; POslo 111, 246 <span class=\"greek\">μηδένα</span> <span class=\"greek\">ἄλλον</span> com a linha 292 <span class=\"greek\">μηδένα</span> <span class=\"greek\">ἕτερον</span>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.10.23\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 10:23</a> com variante; Mlt-Turner 197s. <span class=\"greek\">εἰς</span> <span class=\"greek\">ἕ</span>. <span class=\"greek\">εὐαγγέλιον</span> <span class=\"greek\">ὸ̔</span> <span class=\"greek\">οὐκ</span> <span class=\"greek\">ἔστιν</span> <span class=\"greek\">ἄλλο</span>, «para outro evangelho, que absolutamente não é (outro) evangelho», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.1.6\" target=\"_blank\" rel=\"noopener noreferrer\">Gl 1:6</a>s. (ver <span class=\"greek\">ἄλλος</span> 2b). Para outra análise, cf. ②. <span class=\"greek\">ἄλλον</span> <span class=\"greek\">Ἰησοῦν</span> … <span class=\"greek\">πνεῦμα</span> <span class=\"greek\">ἕ</span>. … <span class=\"greek\">εὐαγγέλιον</span> <span class=\"greek\">ἕ</span>., <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.11.4\" target=\"_blank\" rel=\"noopener noreferrer\">2Co 11:4</a>. Ver também <span class=\"greek\">δ</span>.</p><p class=\"entry-text\">ⓑ <span class=\"greek\">δ</span>. Em enumerações (Atenágoras 4, 1 <span class=\"greek\">ἕ</span>. <span class=\"greek\">μὲν</span> … <span class=\"greek\">ἄλλο</span> <span class=\"greek\">δἐ</span>; 26, 2 <span class=\"greek\">ἄλλους</span> <span class=\"greek\">μὲν</span> … <span class=\"greek\">ἐφ</span>’ <span class=\"greek\">ἑτέρων</span> <span class=\"greek\">δέ</span>): <span class=\"greek\">ὸ̔</span> <span class=\"greek\">μὲν</span> … <span class=\"greek\">καὶ</span> <span class=\"greek\">ἕτερον</span> … <span class=\"greek\">καὶ</span> <span class=\"greek\">ἕ</span>. … <span class=\"greek\">καὶ</span> <span class=\"greek\">ἕ</span>., «uns … outros …», Lc 8:(5), 6, 7, 8. <span class=\"greek\">ὸ̔ς</span> <span class=\"greek\">μὲν</span> … <span class=\"greek\">ἄλλος</span> <span class=\"greek\">δὲ</span> … <span class=\"greek\">ἕτερος</span> … <span class=\"greek\">ἄλλος</span> <span class=\"greek\">δὲ</span> … <span class=\"greek\">ἄλλος</span> <span class=\"greek\">δὲ</span> … <span class=\"greek\">ἕτερος</span> …, 1Co 12:(8), 9, 10; <span class=\"greek\">τὶς</span> … <span class=\"greek\">ἕ</span>., <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.3.4\" target=\"_blank\" rel=\"noopener noreferrer\">1Co 3:4</a>; <span class=\"greek\">τὶς</span> … <span class=\"greek\">ἕ</span>. … <span class=\"greek\">ἄλλος</span> <span class=\"greek\">τις</span>, Lc 22:(56), 58, (59). <span class=\"greek\">πρῶτος</span> … <span class=\"greek\">ἕ</span>., Lc 16:(5), 7; <span class=\"greek\">πρῶτος</span> … <span class=\"greek\">και</span> <span class=\"greek\">ἕ</span>., Lc 14:(18), 19s. <span class=\"greek\">ὁ</span> <span class=\"greek\">πρῶτος</span> … <span class=\"greek\">ὁ</span> <span class=\"greek\">δεύτερος</span> … <span class=\"greek\">ὁ</span> <span class=\"greek\">ἕ</span>., «o primeiro … o segundo … o terceiro», Lc 19:(16, 18), 20; <span class=\"greek\">δοῦλος</span> … <span class=\"greek\">ἕ</span>. <span class=\"greek\">δοῦλος</span> … <span class=\"greek\">τρίτος</span>, Lc 20:(10), 11, (12). Plural: <span class=\"greek\">τινὲς</span> … <span class=\"greek\">ἕτεροι</span>, Lc 11:(15), 16; <span class=\"greek\">ἄλλοι</span> … <span class=\"greek\">ἕ</span>. (PParis 26, 31 [163/162 a.C.]), Hb 11:(35), 36; <span class=\"greek\">οἱ</span> <span class=\"greek\">μὲν</span> … <span class=\"greek\">ἄλλοι</span> <span class=\"greek\">δὲ</span> … <span class=\"greek\">ἕ</span>. <span class=\"greek\">δὲ</span> …, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.16.14\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 16:14</a>.</p><p class=\"entry-text\">ⓑ <span class=\"greek\">ε</span>. <span class=\"greek\">ὁ</span> <span class=\"greek\">ἕτερος</span>, «o próximo»; aqui o contraste é com <span class=\"greek\">αὐτός</span> («o próprio»), como em Demóstenes 34, 12, <span class=\"greek\">ἕ</span>. <span class=\"greek\">ἤδη</span> <span class=\"greek\">ἦν</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">οὐχ</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">αὐτός</span>; cf. Is 34:14. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.2.1\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 2:1</a>; 13:8 (W. Marxsen, TZ 11 [1955], 230–37; porém ver F. Danker, *F. Gingrich Festschrift* [1972], 111, nota 2); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.6.1\" target=\"_blank\" rel=\"noopener noreferrer\">1Co 6:1</a>; 10:24, 29; 14:17; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.6.4\" target=\"_blank\" rel=\"noopener noreferrer\">Gl 6:4</a>. Sem artigo: <span class=\"greek\">διδάσκων</span> <span class=\"greek\">ἕτερον</span> <span class=\"greek\">σεαυτὸν</span> <span class=\"greek\">οὐ</span> <span class=\"greek\">διδάσκεις</span>;, «tu, que ensinas a outro, não ensinas a ti mesmo?», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.2.21\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 2:21</a>; cf. Élio Aristides 28, 1 K. = 49, p. 491 D., <span class=\"greek\">νουθετεῖν</span> <span class=\"greek\">ἑτέρους</span> <span class=\"greek\">ἀφέντες</span> <span class=\"greek\">ἑαυτούς</span>. No plural: <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.2.4\" target=\"_blank\" rel=\"noopener noreferrer\">Fp 2:4</a>.</p><p class=\"entry-text\">ⓑ <span class=\"greek\">ζ</span>. <span class=\"greek\">τῇ</span> <span class=\"greek\">ἑτέρᾳ</span> (subentendido <span class=\"greek\">ἡμέρᾳ</span>), «no dia seguinte» (Xenofonte, Cyr. 4, 6, 10), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.20.15\" target=\"_blank\" rel=\"noopener noreferrer\">At 20:15</a>; 27:3. <span class=\"greek\">ἐν</span> <span class=\"greek\">ἑτέρῳ</span>, «em outro lugar» (nas Escrituras; cf. Josefo, Ant. 14, 114; Justino, D. 58, 8 <span class=\"greek\">ἐν</span> <span class=\"greek\">ἑτέροις</span> etc.), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.13.35\" target=\"_blank\" rel=\"noopener noreferrer\">At 13:35</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.5.6\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 5:6</a>. <span class=\"greek\">εἰς</span> <span class=\"greek\">οὐδὲν</span> <span class=\"greek\">ἕτερον</span> … <span class=\"greek\">ἤ</span>, «a nenhuma outra coisa senão», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.17.21\" target=\"_blank\" rel=\"noopener noreferrer\">At 17:21</a>; cf. CPR I, 32, 15 <span class=\"greek\">οὐδὲν</span> <span class=\"greek\">δὲ</span> <span class=\"greek\">ἕτερον</span>; Josefo, Ant. 8, 104; Taciano 14, 2 <span class=\"greek\">οὐδὲν</span> … <span class=\"greek\">ἕτερον</span> <span class=\"greek\">ἤ</span>.</p><p class=\"entry-text\">② <strong>De espécie ou classe diferente de todas as outras entidades: outro; diferente do anterior</strong>, exterior ou interiormente. Cf. Platão, Symp. 186b <span class=\"greek\">ἕτερος</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ἀνόμοιος</span>; OGI 458, 8 [c. 9 a.C.] <span class=\"greek\">ἑτέραν</span> <span class=\"greek\">ὄψιν</span>; POxy 939, 18; Wsd 7:5; Jt 8:20; TestSol 11:3 <span class=\"greek\">ἑτέραν</span> <span class=\"greek\">πρᾶξιν</span>; Justino, D. 6, 1 <span class=\"greek\">ἕ</span>. … <span class=\"greek\">τι</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">μετέχον</span> <span class=\"greek\">τινὸς</span> <span class=\"greek\">ἐκείνου</span> <span class=\"greek\">οὗ</span> <span class=\"greek\">μετέχει</span>; 55, 1 <span class=\"greek\">ἕ</span>. <span class=\"greek\">θεὸς</span> <span class=\"greek\">παρὰ</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">ποιητὴν</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">ὅλων</span>; 119, 3 <span class=\"greek\">ἡμεῖς</span> <span class=\"greek\">λαὸς</span> <span class=\"greek\">ἕ</span>. <span class=\"greek\">ἀνεθήλαμεν</span>, <span class=\"greek\">καὶ</span> <span class=\"greek\">ἐβλαστήσαμεν</span> <span class=\"greek\">στάχυες</span> <span class=\"greek\">καινοί</span>. <span class=\"greek\">ἐν</span> <span class=\"greek\">ἑ</span>. <span class=\"greek\">μορφῇ</span>, «sob forma diferente», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.16.12\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 16:12</a> (cf. Atenágoras 26, 3 <span class=\"greek\">εἰς</span> <span class=\"greek\">ἕ</span>. <span class=\"greek\">σχῆμα</span>); <span class=\"greek\">εἶδος</span> <span class=\"greek\">ἕτερον</span>, «outra aparência», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.9.29\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 9:29</a> (TestSol 15:3). <span class=\"greek\">ἑτέρα</span> … <span class=\"greek\">δόξα</span>, <span class=\"greek\">ἑτέρα</span> …, «um tipo de glória … outro tipo», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.15.40\" target=\"_blank\" rel=\"noopener noreferrer\">1Co 15:40</a>. <span class=\"greek\">ἕ</span>. <span class=\"greek\">νόμος</span>, «outra lei», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.7.23\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 7:23</a>. <span class=\"greek\">ἑ</span>. <span class=\"greek\">γνῶσις</span>, «outro conhecimento», B 18:1. <span class=\"greek\">ἑ</span>. <span class=\"greek\">ὁδός</span>, «outro caminho», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.2.25\" target=\"_blank\" rel=\"noopener noreferrer\">Tg 2:25</a>. <span class=\"greek\">ἑ</span>. <span class=\"greek\">διδαχή</span>, «outro ensino», Hs 8, 6, 5 (variante <span class=\"greek\">ξένος</span>). Sobre <span class=\"greek\">ἕ</span>. nesse sentido em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.1.6\" target=\"_blank\" rel=\"noopener noreferrer\">Gl 1:6</a>, ver M-M, s.v. Também <strong>estranho, estrangeiro</strong>: <span class=\"greek\">ἐν</span> <span class=\"greek\">χείλεσιν</span> <span class=\"greek\">ἑτέρων</span>, «por lábios de estrangeiros», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.14.21\" target=\"_blank\" rel=\"noopener noreferrer\">1Co 14:21</a> (cf. Is 28:11). <span class=\"greek\">λαλεῖν</span> <span class=\"greek\">ἑτέραις</span> <span class=\"greek\">γλώσσαις</span> em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.2.4\" target=\"_blank\" rel=\"noopener noreferrer\">At 2:4</a> pode significar tanto «falar em línguas diferentes» (até mesmo de sua língua própria) quanto «falar em línguas estrangeiras» (cf. Is 28:11; prólogo de Sirácida, linha 22; 1QH 4, 16); ver <span class=\"greek\">γλῶσσα</span> 3. Bibliografia: J. K. Elliott, ZNW 60 (1969), 140s.; Schmidt, Syn. IV 559–69; DELG; M-M; EDNT; TW.</p></section></article>\n<article id=\"entry-heteros-adv-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἑτέρως</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦hetérōs⟧</span><span class=\"separator\">·</span><span>advérbio</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">Ver o verbete precedente. Atestado desde Homero e outros, mais comum em Platão e posteriores; SIG 851, 10; POxy 34, 15 [séc. II d.C.]; Fílon, Aet. M. 28; Josefo, C. Ap. 1, 26; Atenágoras 19, 1, R. 54, 13. <strong>Diferentemente; de outro modo</strong>: <span class=\"greek\">ἑ</span>. <span class=\"greek\">φρονεῖν</span>, «pensar de outro modo», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.3.15\" target=\"_blank\" rel=\"noopener noreferrer\">Fp 3:15</a>. Bibliografia: M-M.</p></section></article>\n<article id=\"entry-eti-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἔτι</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦éti⟧</span><span class=\"separator\">·</span><span>advérbio</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\"><span class=\"greek\">ἔτι</span>, advérbio; desde Homero.</p><p class=\"entry-text\">① <strong>Continuidade: ainda, até agora.</strong> Contraste <span class=\"greek\">ἤδη</span>, «já», e <span class=\"greek\">ἔτι</span>, «ainda», em Cáriton 49.</p><p class=\"entry-text\">ⓐ Em enunciados afirmativos, indica que uma situação continua: <strong>ainda</strong>.</p><p class=\"entry-text\">ⓐ <span class=\"greek\">α</span>. <strong>No presente:</strong> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.14.32\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 14:32</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.11.4\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 11:4</a>. <span class=\"greek\">ἔ</span>. <span class=\"greek\">σαρκικοί</span> <span class=\"greek\">ἐστε</span>, «ainda sois carnais», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.3.3\" target=\"_blank\" rel=\"noopener noreferrer\">1Co 3:3</a>; <span class=\"greek\">ἔ</span>. <span class=\"greek\">ἐστὲ</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">ταῖς</span> <span class=\"greek\">ἁμαρτίαις</span>, «ainda estais em vossos pecados», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.15.17\" target=\"_blank\" rel=\"noopener noreferrer\">1Co 15:17</a>. <span class=\"greek\">ἔ</span>. <span class=\"greek\">ὑπὸ</span> <span class=\"greek\">κίνδυνόν</span> <span class=\"greek\">εἰμι</span>, «ainda estou em perigo», ITr 13:3. <span class=\"greek\">εἰ</span> <span class=\"greek\">ἔτι</span> <span class=\"greek\">ἀνθρώποις</span> <span class=\"greek\">ἤρεσκον</span>, «se eu ainda procurasse agradar aos homens», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.1.10\" target=\"_blank\" rel=\"noopener noreferrer\">Gl 1:10</a>; 5:11a. <span class=\"greek\">καὶ</span> <span class=\"greek\">τούτοις</span> <span class=\"greek\">ἔτι</span> <span class=\"greek\">κεῖται</span> <span class=\"greek\">μετάνοια</span>, «também a estes permanece aberta a possibilidade de arrependimento», Hs 6, 7, 2. <span class=\"greek\">ἔτι</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">νῦν</span>, «ainda agora», Dg 2:3; cf. Justino, D. 7, 2; A I, 26, 5 <span class=\"greek\">καὶ</span> <span class=\"greek\">νῦν</span> <span class=\"greek\">ἔτι</span>; A II, 6, 6 <span class=\"greek\">καὶ</span> <span class=\"greek\">ἔτι</span> <span class=\"greek\">νῦν</span>.</p><p class=\"entry-text\">ⓐ <span class=\"greek\">β</span>. <strong>No passado</strong>, com o imperfeito: Arriano, Anab. 6, 13, 2, <span class=\"greek\">ἔτι</span> <span class=\"greek\">ἠπίστουν</span>, «ainda não criam». <span class=\"greek\">ἔ</span>. <span class=\"greek\">ἐν</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">ὀσφύϊ</span> <span class=\"greek\">ἦν</span>, «ainda estava nos lombos» (isto é, ainda não fora gerado), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.7.10\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 7:10</a>; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.11.30\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 11:30</a>. Com frequência ocorre com o particípio presente no lugar do imperfeito: Diógenes Laércio 9, 86, <span class=\"greek\">ἔτι</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">ἥλιος</span> <span class=\"greek\">ἀνίσχων</span>. <span class=\"greek\">ἔ</span>. <span class=\"greek\">αὐτοῦ</span> <span class=\"greek\">λαλοῦντος</span>, «enquanto ele ainda falava» (cf. Jó 1:16, 17, 18; TestAbr A 12, p. 90, 14 [Stone p. 28]; Josefo, Ant. 8, 282), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.12.46\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 12:46</a>; 17:5; 26:47; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.5.35\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 5:35</a>a; 14:43; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.8.49\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 8:49</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.10.44\" target=\"_blank\" rel=\"noopener noreferrer\">At 10:44</a> e outros. <span class=\"greek\">εἶπεν</span> <span class=\"greek\">ἔτι</span> <span class=\"greek\">ζῶν</span>, «disse enquanto ainda vivia», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.27.63\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 27:63</a> (Josefo, Ant. 4, 316; 8, 2 <span class=\"greek\">ζῶν</span> <span class=\"greek\">ἔ</span>.). <span class=\"greek\">ἔ</span>. <span class=\"greek\">προσερχομένου</span> <span class=\"greek\">αὐτοῦ</span>, «enquanto ele ainda se aproximava», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.9.42\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 9:42</a>. <span class=\"greek\">ἔ</span>. <span class=\"greek\">αὐτοῦ</span> <span class=\"greek\">μακρὰν</span> <span class=\"greek\">ἀπέχοντος</span>, «quando ainda estava longe», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.15.20\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 15:20</a>. <span class=\"greek\">σκοτίας</span> <span class=\"greek\">ἔ</span>. <span class=\"greek\">οὔσης</span>, «quando ainda estava escuro», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.20.1\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 20:1</a>. <span class=\"greek\">ἔ</span>. <span class=\"greek\">ὢν</span> <span class=\"greek\">πρὸς</span> <span class=\"greek\">ὑμᾶς</span>, «quando eu ainda estava convosco», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TH.2.5\" target=\"_blank\" rel=\"noopener noreferrer\">2Ts 2:5</a>; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.24.6\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 24:6</a>, 41, 44; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.9.1\" target=\"_blank\" rel=\"noopener noreferrer\">At 9:1</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.5.6\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 5:6</a>, 8; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.9.8\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 9:8</a>. <span class=\"greek\">ὄντος</span> <span class=\"greek\">ἔτι</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">σαρκί</span> <span class=\"greek\">σου</span>, «enquanto ainda estás vivo», AcPlCor 1:6; cf. TestAbr A 9, p. 87, 3 [Stone p. 22] <span class=\"greek\">ἔτι</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τούτῳ</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">σώματι</span> <span class=\"greek\">ὤν</span>; Justino, D. 49, 7 <span class=\"greek\">ἔτι</span> <span class=\"greek\">ὄντος</span> <span class=\"greek\">τότε</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">ἀνθρώποις</span> <span class=\"greek\">Μωυσέως</span>.</p><p class=\"entry-text\">ⓐ <span class=\"greek\">γ</span>. <strong>No futuro:</strong> <span class=\"greek\">πλησθήσεται</span> <span class=\"greek\">ἔ</span>. <span class=\"greek\">ἐκ</span> <span class=\"greek\">κοιλίας</span>, «será cheio enquanto ainda estiver no ventre materno», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.15\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 1:15</a>; cf. <span class=\"greek\">ἔ</span>. <span class=\"greek\">ἐκ</span> <span class=\"greek\">κοι</span>. em Is 48:8, também Is 43:13 e Anth. Pal. 9, 567, 1 <span class=\"greek\">ἔ</span>. <span class=\"greek\">ἐκ</span> <span class=\"greek\">βρέφεος</span>; Ps.-Plutarco, Mor. 104d. <span class=\"greek\">καὶ</span> <span class=\"greek\">ἔ</span>. <span class=\"greek\">ῥύσεται</span>, «e ele nos livrará novamente», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.1.10\" target=\"_blank\" rel=\"noopener noreferrer\">2Co 1:10</a>; cf. PsSol 9:11 <span class=\"greek\">εἰς</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">αἰῶνα</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ἔτι</span> e outros.</p><p class=\"entry-text\">ⓑ Em <strong>enunciados negativos</strong>.</p><p class=\"entry-text\">ⓑ <span class=\"greek\">α</span>. <span class=\"greek\">οὐδὲ</span> <span class=\"greek\">ἔ</span>. <span class=\"greek\">νῦν</span>, «nem mesmo agora», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.3.2\" target=\"_blank\" rel=\"noopener noreferrer\">1Co 3:2</a>; ver <span class=\"greek\">νῦν</span> 1a<span class=\"greek\">β</span>ג.</p><p class=\"entry-text\">ⓑ <span class=\"greek\">β</span>. Para indicar que algo <strong>está cessando, cessou ou deve cessar: já não; não mais</strong>. Cf. PsSol 3:12 e outros; TestSol D 4:9 <span class=\"greek\">τέθνηκεν</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">οὐκ</span> <span class=\"greek\">ἔτι</span> <span class=\"greek\">ἴδῃς</span> <span class=\"greek\">αὐτόν</span>; ApcMos 13; Arriano, Anab. 5, 25, 3 e 6; 6, 29, 2a, <span class=\"greek\">οὐ</span> <span class=\"greek\">ἔτι</span>, «não mais»; Esopo, Fab. 243 H. = Ch. 200, p. 333, 52, <span class=\"greek\">μὴ</span> <span class=\"greek\">ἔτι</span>, «não mais»; Josefo, C. Ap. 1, 72; Justino, D. 5, 4 e outros. <span class=\"greek\">οὐ</span> <span class=\"greek\">δύνῃ</span> <span class=\"greek\">ἔ</span>., «já não podes», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.16.2\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 16:2</a>; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.5.13\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 5:13</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.20.36\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 20:36</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.12.8\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 12:8</a> e outros. <span class=\"greek\">οὐ</span> <span class=\"greek\">μὴ</span> <span class=\"greek\">ἔ</span>., «nunca mais», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.8.12\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 8:12</a>; 10:17 (ambos em Jr 38:34; En 5:8; TestAbr B 3, p. 107, 21 [Stone p. 62]; GrBar 1:7); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.18.21\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 18:21</a>, 22, 23. Semelhantemente, em perguntas retóricas: <span class=\"greek\">τί</span> <span class=\"greek\">ἔ</span>. <span class=\"greek\">σκύλλεις</span> <span class=\"greek\">τ</span>. <span class=\"greek\">διδάσκαλον</span>;, «por que incomodas ainda o Mestre?», ou seja, «não o incomodes mais», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.5.35\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 5:35</a>b. «Que necessidade temos ainda de testemunhas?», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.26.65\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 26:65</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.14.63\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 14:63</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.22.71\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 22:71</a>. Também <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.6.2\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 6:2</a>.</p><p class=\"entry-text\">ⓒ <strong>Tempo que ainda não se completou:</strong> <span class=\"greek\">ἔ</span>. (<span class=\"greek\">χρόνον</span>) <span class=\"greek\">μικρόν</span>, «por mais um pouco de tempo», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.7.33\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 7:33</a>; 12:35; 13:33; 14:19; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.10.37\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 10:37</a> (TestJob 24:1); <span class=\"greek\">ἔ</span>. <span class=\"greek\">τετράμηνός</span> <span class=\"greek\">ἐστιν</span> <span class=\"greek\">καί</span>, «ainda faltam quatro meses para», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.4.35\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 4:35</a>; cf. PParis 18 <span class=\"greek\">ἔ</span>. <span class=\"greek\">δύο</span> <span class=\"greek\">ἡμέρας</span> <span class=\"greek\">ἔχομεν</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">φθάσομεν</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">Πηλοῦσι</span>.</p><p class=\"entry-text\">② <strong>Referente à quantidade.</strong></p><p class=\"entry-text\">ⓐ <strong>O que falta ou resta:</strong> TestAbr A 14, p. 93, 26 [Stone p. 34] <span class=\"greek\">τί</span> <span class=\"greek\">ἔτι</span> <span class=\"greek\">λείπεται</span>;, «que falta ainda?». <span class=\"greek\">ἔ</span>. <span class=\"greek\">ἕνα</span> <span class=\"greek\">εἶχεν</span> <span class=\"greek\">υἱόν</span>, «ainda tinha um filho», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.12.6\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 12:6</a>. <span class=\"greek\">τί</span> <span class=\"greek\">ἔ</span>. <span class=\"greek\">ὑστερῶ</span>;, «que me falta ainda?», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.19.20\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 19:20</a>; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.18.22\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 18:22</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.16.12\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 16:12</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.9.12\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 9:12</a>.</p><p class=\"entry-text\">ⓑ <strong>O que é acrescentado ao já existente: além disso; mais; também; outro</strong>: GrBar 16:3 <span class=\"greek\">ἔ</span>. <span class=\"greek\">σὺν</span> <span class=\"greek\">τούτοις</span>; Justino, D. 8, 1 <span class=\"greek\">ἔ</span>. <span class=\"greek\">ἄλλα</span> <span class=\"greek\">πολλά</span>; Taciano 20, 1 <span class=\"greek\">κόσμος</span> … <span class=\"greek\">ἡμᾶς</span> <span class=\"greek\">ἔ</span>. <span class=\"greek\">καθέλκει</span>. <span class=\"greek\">ἔ</span>. <span class=\"greek\">ἕνα</span> <span class=\"greek\">ἢ</span> <span class=\"greek\">δύο</span>, «mais um ou dois», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.18.16\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 18:16</a>; <span class=\"greek\">ἔ</span>. <span class=\"greek\">τοῦτο</span> … <span class=\"greek\">δεῖ</span> <span class=\"greek\">τελεσθῆναι</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.22.37\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 22:37</a>, variante; <span class=\"greek\">ἔ</span>. <span class=\"greek\">προ</span>[<span class=\"greek\">σθείς</span>], «enquanto ele acrescentava», Ox 1081 (SJCh) 9, segundo Wessely. <span class=\"greek\">ἔ</span>. <span class=\"greek\">δέ</span>: Xenofonte, Mem. 1, 2, 1; Diodoro Sículo 1, 74, 1; 13, 81, 3; Estrabão 10, 3, 7; Dião Crisóstomo 36 [53], 1; 2Mc 6:4; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.11.36\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 11:36</a>. <span class=\"greek\">ἔ</span>. <span class=\"greek\">δὲ</span> <span class=\"greek\">καί</span>, «além disso» (Xenofonte, An. 3, 2, 28 e outros; UPZ 61, 10 [161 a.C.]; PMich 174, 7 [146 d.C.]; 2Esd 19:18; EpArist 151; Josefo, Bell. 2, 546, Ant. 7, 70; Ar. 4:3 e outros; Justino, D. 34, 1; Taciano 29, 1 e outros; Melitão, HE 4, 26, 13; Atenágoras 13, 1): <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.2.26\" target=\"_blank\" rel=\"noopener noreferrer\">At 2:26</a> (Sl 15:9); 1Cl 17:1, 3; Hs 5, 2, 5; B 4:6; AcPl Ox 6, 20 (= Aa I 242, 2) e outros. <span class=\"greek\">ἔ</span>. <span class=\"greek\">τε</span> <span class=\"greek\">καί</span>: Josefo, Ant. 14, 194; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.14.26\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 14:26</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.21.28\" target=\"_blank\" rel=\"noopener noreferrer\">At 21:28</a>. <span class=\"greek\">ἔ</span>. <span class=\"greek\">ἄνω</span>, <span class=\"greek\">ἔ</span>. <span class=\"greek\">κάτω</span>, «mais acima, mais abaixo», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.20.28\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 20:28</a> D. <span class=\"greek\">ἔ</span>. <span class=\"greek\">ἅπαξ</span>, «mais uma vez» (2Mc 3:37; TestAbr A 9, p. 86, 24 [Stone p. 20] e outros; ApcSed 12:2), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.12.26\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 12:26</a>s. (Ag 2:6). Com comparativo: <span class=\"greek\">ἔ</span>. <span class=\"greek\">μᾶλλον</span>, «ainda mais» (Homero e outros; POxy 939, 3; Josefo, Ant. 20, 89), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.1.9\" target=\"_blank\" rel=\"noopener noreferrer\">Fp 1:9</a>; <span class=\"greek\">περισσότερον</span> <span class=\"greek\">ἔ</span>., <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.7.15\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 7:15</a>. <span class=\"greek\">ἔ</span>. <span class=\"greek\">καί</span> <span class=\"greek\">ἔ</span>., «repetidas vezes», B 21:4; Hs 2:6.</p><p class=\"entry-text\">③ <strong>Em inferência lógica, em frases interrogativas</strong> (Justino, D. 7, 1, 151, <span class=\"greek\">τίνι</span> <span class=\"greek\">οὖν</span> … <span class=\"greek\">ἔ</span>. <span class=\"greek\">τις</span> <span class=\"greek\">χρήσαιτο</span> <span class=\"greek\">διδασκάλῳ</span>;): <span class=\"greek\">τίς</span> <span class=\"greek\">ἔ</span>. <span class=\"greek\">χρεία</span>;, «que necessidade adicional haveria?», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.7.11\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 7:11</a>; <span class=\"greek\">τί</span> <span class=\"greek\">ἔ</span>. <span class=\"greek\">μέμφεται</span>;, «por que, então, [Deus] ainda encontra falta?», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.9.19\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 9:19</a>; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.3.7\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 3:7</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.5.11\" target=\"_blank\" rel=\"noopener noreferrer\">Gl 5:11</a>b. Bibliografia: DELG; M-M.</p></section></article>\n<article id=\"entry-hetoimazo-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἑτοιμάζω</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦hetoimázō⟧</span><span class=\"separator\">·</span><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\"><span class=\"greek\">ἑτοιμάζω</span>: futuro <span class=\"greek\">ἑτοιμάσω</span>; primeiro aoristo <span class=\"greek\">ἡτοίμασα</span>; perfeito <span class=\"greek\">ἡτοίμακα</span>. Passivo: futuro <span class=\"greek\">ἑτοιμασθήσομαι</span> (LXX); primeiro aoristo <span class=\"greek\">ἡτοιμάσθην</span>; perfeito passivo <span class=\"greek\">ἡτοίμασμαι</span>. Ver <span class=\"greek\">ἑτοιμασία</span> e <span class=\"greek\">ἕτοιμος</span>; atestado desde Homero. <strong>Tornar pronto; colocar ou manter em estado de prontidão; preparar.</strong></p><p class=\"entry-text\">ⓐ <strong>Coisas postas em prontidão</strong>, com acusativo da coisa (<span class=\"greek\">τὶ</span>). Preparar <strong>um caminho</strong>: <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.3.3\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 3:3</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.1.3\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 1:3</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.3.4\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 3:4</a> (todos de Is 40:3; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.1.23\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 1:23</a> <span class=\"greek\">εὐθύνω</span>, ver este lema); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.76\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 1:76</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.16.12\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 16:12</a>; <strong>uma pira funerária</strong>: MPol 13:2; <strong>uma refeição</strong> (Gn 43:16; EpArist 181; TestAbr B 4, p. 108, 14s. [Stone p. 64]; JosAs 3:6): <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.22.4\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 22:4</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.17.8\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 17:8</a>; cf. 1Cl 39:9. <span class=\"greek\">τὸ</span> <span class=\"greek\">πάσχα</span>, «a Páscoa» (ver este lema): <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.26.19\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 26:19</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.14.16\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 14:16</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.22.13\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 22:13</a>; cf. GEb 308, 31. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.15.1\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 15:1</a>, variante de leitura; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.23.56\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 23:56</a>; 24:1. <span class=\"greek\">ἃ</span> <span class=\"greek\">ἡτοίμασας</span>, «aquilo que preparaste», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.12.20\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 12:20</a>. Referente a bens: Hs 1:1, 2, 4.</p><p class=\"entry-text\">ⓐ Com <strong><span class=\"greek\">τινί</span> <span class=\"greek\">τι</span></strong>, preparar alguma coisa para alguém: Hs 1:6. <span class=\"greek\">θηρίων</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">ἐμοὶ</span> <span class=\"greek\">ἡτοιμασμένων</span>, «as feras preparadas para mim», IRo 5:2. Sobre preparativos para receber ou hospedar alguém (PTebt 592 … <span class=\"greek\">σοῦ</span> <span class=\"greek\">ταχὺ</span> <span class=\"greek\">ἐρχομένου</span> … <span class=\"greek\">ἡτοιμάκειν</span> <span class=\"greek\">σοι</span> <span class=\"greek\">πάντα</span>; POxy 1299, 9; 1490, 7; TestAbr A 4, p. 80, 19, 28 [Stone p. 8]): <span class=\"greek\">ἑτοίμαζέ</span> <span class=\"greek\">μοι</span> <span class=\"greek\">ξενίαν</span>, «prepara-me hospedagem», Fm 22. <span class=\"greek\">ἑ</span>. <span class=\"greek\">τινὶ</span> <span class=\"greek\">τόπον</span>, «preparar lugar para alguém», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.14.2\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 14:2</a>, 3; cf. Apiano, Bell. Civ. 2, 53 §219, sobre os que vão à frente: <span class=\"greek\">ἀσφαλῆ</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">ἐκεῖ</span> <span class=\"greek\">προετοιμάσαι</span>, «preparar ali um lugar seguro [para os que seguem]»; 1Cr 15:1. Sem acusativo objeto, <span class=\"greek\">ἑ</span>. <span class=\"greek\">τινί</span>, «fazer preparativos para alguém», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.9.52\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 9:52</a>. Em outra acepção, «preparar [refeição]», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.14.15\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 14:15</a>.</p><p class=\"entry-text\">ⓐ Uso <strong>absoluto</strong>: 1Esd 1:4; Jr 26:14; Jó 28:27; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.12.47\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 12:47</a>; 22:9, 12. <span class=\"greek\">ὁλοκαύτωμα</span> <span class=\"greek\">δεκτὸν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">θεῷ</span> <span class=\"greek\">ἡτοιμασμένον</span>, «holocausto preparado, aceitável a Deus», MPol 14:1. Com <span class=\"greek\">τινί</span> seguido de infinitivo, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.26.17\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 26:17</a>; com <span class=\"greek\">ἵνα</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.14.12\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 14:12</a>; com <span class=\"greek\">τινί</span> <span class=\"greek\">τι</span> e <span class=\"greek\">ἵνα</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.22.8\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 22:8</a>.</p><p class=\"entry-text\">ⓐ O particípio <strong><span class=\"greek\">ἡτοιμασμένος</span></strong>, «pronto; preparado», com <span class=\"greek\">εἴς</span> <span class=\"greek\">τι</span>, «para alguma coisa» (3Mc 6:31): de um vaso, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.2.21\" target=\"_blank\" rel=\"noopener noreferrer\">2Tm 2:21</a>; de cavalos <span class=\"greek\">εἰς</span> <span class=\"greek\">πόλεμον</span>, «para a guerra», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.9.7\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 9:7</a>; cf. Pv 21:31 <span class=\"greek\">ἵππος</span> <span class=\"greek\">ἑτοιμάζεται</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">ἡμέραν</span> <span class=\"greek\">πολέμου</span>; também 1Mc 13:22; 12:27; TestLevi 3:2, variante; figuradamente, de pedras de construção, IEph 9:1. Ver ainda os passivos no fim de ⓑ, a começar por <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.10.40\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 10:40</a>.</p><p class=\"entry-text\">ⓑ <strong>Pessoas</strong> (En 99:3; TestJob 43:14; Josefo, Vi. 203): <span class=\"greek\">ἑ</span>. <span class=\"greek\">στρατιώτας</span>, «preparar soldados», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.23.23\" target=\"_blank\" rel=\"noopener noreferrer\">At 23:23</a>; cf. A. Meuwese, *De rer. gest. Divi Augusti vers. graeca* (1920), 82. De uma noiva, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.21.2\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 21:2</a>. <span class=\"greek\">ἑ</span>. <span class=\"greek\">ἑαυτόν</span>, «preparar-se» (Ez 38:7; ParJer 6:6; 9:11; cf. POslo 88, 13 <span class=\"greek\">ἑτοιμάζεσθαι</span> <span class=\"greek\">ἑαυτόν</span>), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.19.7\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 19:7</a>; com <span class=\"greek\">ἵνα</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.8.6\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 8:6</a>. <span class=\"greek\">Ἰωσὴφ</span> <span class=\"greek\">ἡτοιμάσθη</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">ἐξελθεῖν</span>, «José preparou-se para sair», GJs 21:1. Com <span class=\"greek\">εἰς</span> (Apiano, Mithrid. 26 §103; PsSol 10:2 <span class=\"greek\">νῶτον</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">μάστιγας</span>). Dos anjos: <span class=\"greek\">ἡτοιμασμένοι</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">τ</span>. <span class=\"greek\">ὥραν</span>, «mantidos preparados para aquela hora», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.9.15\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 9:15</a>. De Jesus: <span class=\"greek\">ὸ̔ς</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">τοῦτο</span> <span class=\"greek\">ἡτοιμάσθη</span>, <span class=\"greek\">ἵνα</span>, B 14:5. Deus vem <span class=\"greek\">ἐφ</span>’ <span class=\"greek\">οὓς</span> <span class=\"greek\">τ</span>. <span class=\"greek\">πνεῦμα</span> <span class=\"greek\">ἡτοίμασεν</span>, «àqueles que o Espírito preparou», D 4:10; B 19:7.</p><p class=\"entry-text\">ⓑ <strong>Um povo preparado</strong>: 2Rs 7:24; B 3:6; 5:7; 14:6; <span class=\"greek\">τῷ</span> <span class=\"greek\">κυρίῳ</span>, «para o Senhor» (Sir 49:12), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.17\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 1:17</a>. Aqui Deus é várias vezes identificado como aquele que efetua a preparação; no passivo seguinte, figura explicitamente como agente, tendo pessoa ou coisa como objeto (Êx 23:20; En 25:7; PsSol 5:10 <span class=\"greek\">χορτάσματα</span> … <span class=\"greek\">παντὶ</span> <span class=\"greek\">ζῶντι</span>; JosAs 8:11 <span class=\"greek\">κατάπαυσιν</span> … <span class=\"greek\">τοῖς</span> <span class=\"greek\">ἐκλεκτοῖς</span>; ApcEsdr 6:17, 21 <span class=\"greek\">ὁ</span> <span class=\"greek\">στέφανός</span> <span class=\"greek\">σοι</span> <span class=\"greek\">ἡτοίμασται</span>): <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.20.23\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 20:23</a>; <span class=\"greek\">βασιλείαν</span>, «reino», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.25.34\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 25:34</a>; D 10:5; <span class=\"greek\">πῦρ</span>, «fogo», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.25.41\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 25:41</a>. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.10.40\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 10:40</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.2.31\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 2:31</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.2.9\" target=\"_blank\" rel=\"noopener noreferrer\">1Co 2:9</a> = 1Cl 34:8 (citação de origem desconhecida); cf. 2Cl 14:5; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.11.16\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 11:16</a> (<span class=\"greek\">πόλιν</span> <span class=\"greek\">ἑ</span>., como Hc 2:12); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.12.6\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 12:6</a>; 1Cl 35:3; Dg 8:11. Bibliografia: M-M; TW.</p></section></article>\n<article id=\"entry-hetoimas-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Ἕτοιμας</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦Hétoimas⟧</span><span class=\"separator\">·</span><span>nome próprio</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">Remissão lexicográfica: ver <span class=\"greek\">Ἐλύμας</span>.</p></section></article>\n<article id=\"entry-hetoimasia-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἑτοιμασία, ας, ἡ</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦hetoimasía⟧</span><span class=\"separator\">·</span><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">Genitivo <span class=\"greek\">ας</span>. Ver o verbete seguinte. Atestações: Hipócrates; BGU 625, 17; PHerm 95, 20; LXX. <strong>Prontidão; preparação</strong>: Hipócrates, Decent. 12, vol. IX, p. 240 L.; Sl 9:38; EpArist 182; Josefo, Ant. 10, 9, variante de leitura. Em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.6.15\" target=\"_blank\" rel=\"noopener noreferrer\">Ef 6:15</a>, <span class=\"greek\">τοῦ</span> <span class=\"greek\">εὐαγγελίου</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">εἰρήνης</span> significa «do evangelho da paz». A interpretação <strong>equipamento</strong>, particularmente «calçados/botas», como no grego moderno, é favorecida por A. Buscarlet, ET 9 (1897/98), 38s.; E. Blakeney, ET 55 (1943/44), 138; J. Gregg, ET 56 (1944), 54; L-S-J-M. Em associação com <span class=\"greek\">ἄσκησις</span>: MPol 18:3. Bibliografia: M-M; TW.</p></section></article>\n<article id=\"entry-hetoimos-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἕτοιμος, η, ον</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦hétoimos⟧</span><span class=\"separator\">·</span><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\"><span class=\"greek\">ἕτοιμος</span>, <span class=\"greek\">η</span>, <span class=\"greek\">ον</span>. Ver <span class=\"greek\">ἑτοιμάζω</span>, <span class=\"greek\">ἑτοιμασία</span> e <span class=\"greek\">ἑτοίμως</span>. Adjetivo de duas terminações no plural, conforme Jt 9:6; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.25.10\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 25:10</a>; B-D-F §59, 2; Mlt-H. 157. <strong>Pronto, preparado.</strong></p><p class=\"entry-text\">ⓐ <strong>Coisas destinadas a servir a certo fim</strong> (empréstimo lexical no rabínico; Homero e posteriores; inscrições, papiros, LXX, Fílon; Josefo, Ant. 7, 339 <span class=\"greek\">πάντα</span>). De um altar, IRo 2:2. De preparativos para uma refeição (cf. Dt 32:35): <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.22.4\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 22:4</a> (Apiano, Bell. Civ. 1, 56 §246 <span class=\"greek\">πάντα</span> <span class=\"greek\">ἕτοιμα</span>; BGU 625, 13 [séc. III d.C.] <span class=\"greek\">πάντα</span> <span class=\"greek\">ἕ</span>.), v. 8; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.14.17\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 14:17</a>; de uma refeição já «servida», Ps.-Clemente, Hom. 5, 30. A chamada à refeição imediatamente antes de ela ser servida: Est 6:14; Fílon, Op. M. 78; Luciano, Merc. Cond. 14. De um refeitório preparado: <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.14.15\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 14:15</a>. De uma coleta para os santos: <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.9.5\" target=\"_blank\" rel=\"noopener noreferrer\">2Co 9:5</a>. <span class=\"greek\">τὰ</span> <span class=\"greek\">ἕ</span>., «aquilo que foi realizado [por outra pessoa]», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.10.16\" target=\"_blank\" rel=\"noopener noreferrer\">2Co 10:16</a>. <span class=\"greek\">καιρός</span>, «o tempo está pronto», isto é, «chegou», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.7.6\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 7:6</a>. Com infinitivo de finalidade (Est 1:1e): <span class=\"greek\">σωτηρία</span> <span class=\"greek\">ἑ</span>. <span class=\"greek\">ἀποκαλυφθῆναι</span>, «salvação pronta para ser revelada», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.1.5\" target=\"_blank\" rel=\"noopener noreferrer\">1Pe 1:5</a>.</p><p class=\"entry-text\">ⓑ <strong>Pessoas</strong> (Píndaro e posteriores; PHib 44, 7 [253 a.C.]; LXX; PsSol 6:1; TestJob 7:13; TestLevi 3:2; JosAs 15:10; Fílon; Josefo; Ar. 15:10; Justino; Taciano). Embrião humano pronto para tornar-se ser vivo no sexto mês: <span class=\"greek\">ἕτοιμον</span> <span class=\"greek\">γίνεται</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">λαμβάνει</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">φυχήν</span>, ApcEsdr 5:13. <strong>Pronto, preparado</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.25.10\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 25:10</a>. <span class=\"greek\">ἕ</span>. <span class=\"greek\">εἰμι</span>, «estou pronto» (Tucídides e outros; PTebt 419, 10; LXX), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.23.21\" target=\"_blank\" rel=\"noopener noreferrer\">At 23:21</a>; Hs 9, 2, 4; seguido de infinitivo (Diodoro Sículo 13, 98, 1 <span class=\"greek\">ἕτοιμός</span> <span class=\"greek\">εἰμι</span> <span class=\"greek\">τελευτᾶν</span>; 1Mc 7:29; 2Mc 7:2; 4Mc 9:1; PsSol 6:1; TestJob 7:13; Josefo, Ant. 10, 9; Ar. 15:10; Justino, A II, 3, 5), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.22.33\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 22:33</a>; com <span class=\"greek\">τοῦ</span> + infinitivo (Mq 6:8; 1Mc 13:37), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.23.15\" target=\"_blank\" rel=\"noopener noreferrer\">At 23:15</a>; Hs 8, 4, 2.</p><p class=\"entry-text\">ⓑ <span class=\"greek\">ἕ</span>. <span class=\"greek\">γίνεσθαι</span>, «estar pronto; preparar-se» (Diodoro Sículo 4, 49, 5 <span class=\"greek\">ἑτοίμους</span> <span class=\"greek\">γενομένους</span>; Ps.-Calístenes 2, 11, 1 e 6; Êx 19:15; Nm 16:16), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.24.44\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 24:44</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.12.40\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 12:40</a>; D 16:1; com <span class=\"greek\">ἵνα</span>, Hs 1:6. <span class=\"greek\">ἕ</span>. <span class=\"greek\">πρός</span> <span class=\"greek\">τι</span>, «pronto para alguma coisa» (Xenofonte, Mem. 4, 5, 12; Eliano, VH 14, 49; BGU 1209, 17 [23 a.C.]; Tb 5:17 BA; Justino, D. 56, 16; Taciano 42, 1): <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/TIT.3.1\" target=\"_blank\" rel=\"noopener noreferrer\">Tt 3:1</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.3.15\" target=\"_blank\" rel=\"noopener noreferrer\">1Pe 3:15</a>. Também <span class=\"greek\">εἴς</span> <span class=\"greek\">τι</span> (Heródoto 8, 96 e outros; 1Mc 4:44; 12:50 e outros; JosAs 15:10; Josefo, Ant. 15, 357): 1Cl 2:7; ISm 11:3; IPol 7:3.</p><p class=\"entry-text\">ⓑ <span class=\"greek\">ἐν</span> <span class=\"greek\">ἑτοίμῳ</span>, «em estado de prontidão» (Epicuro em Diógenes Laércio 10, 127; Teócrito 22, 61 e Epigr. 16, 5; Dionísio de Halicarnasso 8, 17; 9, 35; PGen 76, 8; PGM 13, 375; 3Mc 6:31). <span class=\"greek\">ἐν</span> <span class=\"greek\">ἑτοίμῳ</span> <span class=\"greek\">ἔχειν</span>, «estar pronto» (Políbio 2, 34, 2; Fílon, Leg. ad Gai. 259), seguido de infinitivo: <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.10.6\" target=\"_blank\" rel=\"noopener noreferrer\">2Co 10:6</a>. Comparativo <span class=\"greek\">ἑτοιμότερος</span>, «mais pronto; mais disposto» (Agatárquides [séc. II a.C.], 86 Fgm. 6 Jac.; PFlor 123, 4), 2Cl 15:4. Bibliografia: M-M; TW.</p></section></article>\n<article id=\"entry-hetoimos-adv-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἑτοίμως</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦hetoímōs⟧</span><span class=\"separator\">·</span><span>advérbio</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">Ver o verbete precedente; Ésquilo e posteriores; inscrições, papiros, LXX; Fílon, Spec. Leg. 1, 49. <strong>Prontamente; de boa vontade</strong>. <span class=\"greek\">ἑ</span>. <span class=\"greek\">ἔχειν</span>: «estar pronto; estar disposto», seguido de infinitivo (Enéas Tático 582; Diodoro Sículo 16, 28, 2; PAmh 32, 6 [séc. II a.C.]; BGU 80, 17; POxy 1469, 21; Dn 3:15 LXX; Josefo, Ant. 12, 163; Justino, D. 50, 1): <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.12.14\" target=\"_blank\" rel=\"noopener noreferrer\">2Co 12:14</a>; 13:1, variante de leitura; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.4.5\" target=\"_blank\" rel=\"noopener noreferrer\">1Pe 4:5</a>. Com <span class=\"greek\">ἀποθανεῖν</span>, «morrer»: <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.21.13\" target=\"_blank\" rel=\"noopener noreferrer\">At 21:13</a>; cf. Josefo, Ant. 13, 6 <span class=\"greek\">ἀποθνῄσκειν</span>. Bibliografia: DELG, s.v. <span class=\"greek\">ἑτοῖμο</span> (forma homérica); M-M.</p></section></article>\n<article id=\"entry-etos-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἔτος, ους, τό</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦étos⟧</span><span class=\"separator\">·</span><span>substantivo neutro</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\"><span class=\"greek\">ἔτος</span>, <span class=\"greek\">ους</span>, <span class=\"greek\">τό</span>; desde Homero. <strong>Ano</strong>: <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.7.30\" target=\"_blank\" rel=\"noopener noreferrer\">At 7:30</a>; 13:21; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.1.12\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 1:12</a> (Sl 101:28); 3:10, 17 (Sl 94:10); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.3.8\" target=\"_blank\" rel=\"noopener noreferrer\">2Pe 3:8</a> (Sl 89:4); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.20.3\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 20:3</a>–7; 1Cl 25:5 e outros.</p><p class=\"entry-text\"><strong><span class=\"greek\">ἔτη</span> <span class=\"greek\">ἔχειν</span></strong>, «ter tantos anos de idade» (Josefo, Ant. 1, 198), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.8.57\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 8:57</a>. Em sentido diferente, acrescido de <span class=\"greek\">ἐν</span> <span class=\"greek\">τ</span>. <span class=\"greek\">ἀσθενείᾳ</span> <span class=\"greek\">αὐτοῦ</span>, «estar doente há tantos anos», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.5.5\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 5:5</a> (cf. TestJob 26:1 <span class=\"greek\">ἐν</span> <span class=\"greek\">ταῖς</span> <span class=\"greek\">πληγαῖς</span>). <strong><span class=\"greek\">εἶναι</span>, <span class=\"greek\">γίνεσθαι</span> <span class=\"greek\">ἐτῶν</span></strong> + numeral para exprimir idade (Xenofonte, Mem. 1, 2, 40 e outros; Gn 7:6; 12:4 frequentemente; Demétrio 722 Fgm. 1, 1 e outros Jac.; Josefo, Ant. 10, 50): <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.5.42\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 5:42</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.2.42\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 2:42</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.4.22\" target=\"_blank\" rel=\"noopener noreferrer\">At 4:22</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.5.9\" target=\"_blank\" rel=\"noopener noreferrer\">1Tm 5:9</a> (Cyr. Ins. 16 <span class=\"greek\">μηδένα</span> <span class=\"greek\">νεώτερον</span> <span class=\"greek\">πέντε</span> <span class=\"greek\">κ</span>. <span class=\"greek\">εἴκοσι</span> <span class=\"greek\">ἐτῶν</span>). Com <strong><span class=\"greek\">ὡς</span></strong> ou <strong><span class=\"greek\">ὡσεὶ</span> <span class=\"greek\">ἐτῶν</span></strong> + numeral, «com cerca de tantos anos» (Xenofonte, An. 2, 6, 20 <span class=\"greek\">ἦν</span> <span class=\"greek\">ἐτῶν</span> <span class=\"greek\">ὡς</span> <span class=\"greek\">τριάκοντα</span>; PTebt 381, 4s. [123 a.C.]; ver Deissmann em P. Meyer, *Griech. Texte aus Ägypt.* [1916], p. 26, 48; para números arredondados, Meyer 47, n.º 7, 5, 7; 67, n.º 12, 12): <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.3.23\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 3:23</a>; 8:42; GJs 12:3.</p><p class=\"entry-text\"><strong>Acusativo de duração</strong>, respondendo a «por quanto tempo?» (Xenofonte, Cyr. 1, 2, 9; SIG 1168: 3, 8, 14, 95; SIG² 847, 4; 850, 6 e outros; 2Rs 21:1; EpJer 2; Jt 8:4; 1Mc 1:7, 9; Demétrio 722 Fgm. 1, 6 Jac.; Justino, D. 88, 2). <span class=\"greek\">δώδεκα</span> <span class=\"greek\">ἔτη</span>, «durante doze anos», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.9.20\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 9:20</a>; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.5.25\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 5:25</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.2.36\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 2:36</a>; 13:7s., 11, 16; 15:29; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.7.6\" target=\"_blank\" rel=\"noopener noreferrer\">At 7:6</a> (Gn 15:13), 36, 42 (Am 5:25); B 10:6; MPol 9:3 e outros.</p><p class=\"entry-text\"><strong>Dativo de duração</strong>, em sentido praticamente igual (Apiano, Illyr. 25 §71 <span class=\"greek\">ἔτεσι</span> <span class=\"greek\">δέκα</span>, «durante dez anos»; Polieno 1, 12; Luciano, Dial. Meretr. 8, 2 e outros; SIG 872, 17; 898, 28; 966, 17; inscrição acerca de bispo da Licaônia, Exp. série 7, vol. 6 [1908], 387, 12, <span class=\"greek\">εἴκοσι</span> <span class=\"greek\">πέντε</span> <span class=\"greek\">ὅλοις</span> <span class=\"greek\">ἔτεσιν</span> <span class=\"greek\">τ</span>. <span class=\"greek\">ἐπισκοπὴν</span> <span class=\"greek\">διοικήσας</span>; B-D-F §201; Robertson 523). Sobre o templo: <span class=\"greek\">τεσσεράκοντα</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ἓξ</span> <span class=\"greek\">ἔτεσιν</span> <span class=\"greek\">οἰκοδομήθη</span>, «esteve em construção por quarenta e seis anos», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.2.20\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 2:20</a>; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.13.20\" target=\"_blank\" rel=\"noopener noreferrer\">At 13:20</a>. Igualmente <strong><span class=\"greek\">ἐπί</span> + acusativo</strong> (SIG 1219, 27 <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">δέκα</span> <span class=\"greek\">ἔτη</span>; Mitt-Wilck. 327, 16 [107 a.C.]; Josefo, Ant. 5, 211): <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.4.25\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 4:25</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.19.10\" target=\"_blank\" rel=\"noopener noreferrer\">At 19:10</a>.</p><p class=\"entry-text\"><strong>Outras combinações preposicionais.</strong> <span class=\"greek\">ἀπὸ</span> (SIG 762, 14; 820, 8) <span class=\"greek\">ἐτῶν</span> <span class=\"greek\">δώδεκα</span>, «por doze anos», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.8.43\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 8:43</a>; <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">πολλῶν</span> <span class=\"greek\">ἐ</span>., «há muitos anos», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.15.23\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 15:23</a>. <span class=\"greek\">ἐκ</span> <span class=\"greek\">πολλῶν</span> <span class=\"greek\">ἐ</span>., <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.24.10\" target=\"_blank\" rel=\"noopener noreferrer\">At 24:10</a>; cf. 9:33. <span class=\"greek\">δι</span>’ <span class=\"greek\">ἐ</span>. <span class=\"greek\">πλειόνων</span>, «passados vários anos», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.24.17\" target=\"_blank\" rel=\"noopener noreferrer\">At 24:17</a>; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.2.1\" target=\"_blank\" rel=\"noopener noreferrer\">Gl 2:1</a>. <span class=\"greek\">εἰς</span> <span class=\"greek\">ἔ</span>. <span class=\"greek\">πολλά</span>, «para muitos anos vindouros», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.12.19\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 12:19</a> (cf. SIG 707, 19s.; 708, 43). <span class=\"greek\">ἐν</span> <span class=\"greek\">ἔτει</span> <span class=\"greek\">πεντεκαιδεκάτῳ</span>, «no décimo quinto ano», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.3.1\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 3:1</a> (cf. SIG 736: 11, 52, 54, 90; 3Rs 6:1; 15:1 e outros). <span class=\"greek\">ἕως</span> <span class=\"greek\">ἐτῶν</span> …, «até tantos anos de idade» (cf. Jl 2:2; Josefo, Ant. 5, 181), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.2.37\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 2:37</a>. <span class=\"greek\">κατ</span>’ <span class=\"greek\">ἔτος</span>, «todos os anos» (GDI 4195, 30s. [Rodes]; PAmh 86, 11 [78 d.C.]; POxy 725, 36; 2Mc 11:3; Josefo, Ant. 7, 99), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.2.41\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 2:41</a>. <span class=\"greek\">μετὰ</span> <span class=\"greek\">τρία</span> <span class=\"greek\">ἔ</span>., «depois de três anos», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.1.18\" target=\"_blank\" rel=\"noopener noreferrer\">Gl 1:18</a>; 3:17; cf. SIG 708, 26; Tb 14:2 BA; Is 23:15; Dn 4:33a; 1Mc 1:29; Taciano 31, 3. <span class=\"greek\">πρὸ</span> <span class=\"greek\">ἐτῶν</span> <span class=\"greek\">δεκατεσσάρων</span>, «catorze anos atrás», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.12.2\" target=\"_blank\" rel=\"noopener noreferrer\">2Co 12:2</a> (como Justino, A I, 46, 1). <span class=\"greek\">χιλιάδα</span> <span class=\"greek\">τινὰ</span> … <span class=\"greek\">ἐτῶν</span>, «certo milhar de anos», Papias (2:12). A indicação «catorze anos atrás» reaparece na fonte após essa referência. Bibliografia: B. 1011s.; DELG; M-M.</p></section></article>\n<article id=\"entry-eu-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὖ</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦eû⟧</span><span class=\"separator\">·</span><span>advérbio e interjeição</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\"><span class=\"greek\">εὖ</span>, advérbio; atestado desde Homero; inscrições, papiros, LXX; TestJob 44:3; ParJer 7:9; EpArist; Fílon; Josefo; Ar. [Milne p. 74, linha 1]; Justino; Taciano 17, 3; Atenágoras. <span class=\"greek\">καλῶς</span> tornou-se a forma mais usual: J. Lee, NovT 27 (1985), 11s.</p><p class=\"entry-text\">① <strong>O que é bom ou benéfico nas relações humanas ou na experiência: bem.</strong> <span class=\"greek\">εὖ</span> <span class=\"greek\">ποιεῖν</span>, «fazer o bem; demonstrar bondade» (Xenofonte, Cyr. 1, 6, 30, Oec. 2, 5; Demóstenes 20, 37; POxy 1292, 3 [c. 30 d.C.]; LXX; TestJob 44:3s. [<span class=\"greek\">εὐποιεῖν</span>]; Josefo, Ant. 14, 378; Justino, A I, 28, 3; D. 118, 5), com <span class=\"greek\">τινί</span>, «a alguém» (Êx 1:20; Sir 12:2, 5; mais frequentemente segue-se acusativo), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.14.7\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 14:7</a>. <span class=\"greek\">εὖ</span> <span class=\"greek\">δουλεύειν</span>, «servir bem», 1Cl 16:12 (Is 53:11).</p><p class=\"entry-text\">① <strong><span class=\"greek\">εὖ</span> <span class=\"greek\">πράσσειν</span> (<span class=\"greek\">ποιεῖν</span>)</strong> geralmente significa «passar bem; prosperar» (Píndaro; Xenofonte, Mem. 1, 6, 8; 2, 4, 6; 4, 2, 26; Oec. 11, 8; Platão, Prot. 333d; Ps.-Platão, Alc. I 116b; Diógenes Laércio 3, 61; Fílon, Virt. 170; Decal. 43; Josefo, Ant. 12, 156 e outros; cf. Atenágoras 25, 2). Como fórmula epistolar de despedida, «passai bem», POxy 115, 12; 120, 27; 527, 9; 822; PGen 59, 24; 2Mc 9:19. Esse sentido é possível em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.15.29\" target=\"_blank\" rel=\"noopener noreferrer\">At 15:29</a>, porém «agir bem», isto é, «proceder corretamente», se ajusta melhor ao contexto e encontra apoio nas traduções latina (Vulgata), armênia e copta; assim também Simônides, Fgm. 4, 10 D.²; Xenofonte, Mem. 3, 9, 14; Ps.-Platão, Eryx. 393e; Epicteto 4, 6, 20; Artemidoro 2, 3, p. 86, 13; Marco Aurélio 3, 13; Fílon, Mut. Nom. 197; Josefo, Ant. 4, 286; Justino, A I, 28, 3.</p><p class=\"entry-text\">① <strong>Justificativa documental e sociolinguística:</strong> a expressão de <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.15.23\" target=\"_blank\" rel=\"noopener noreferrer\">At 15:23</a>–29 é apropriada a um documento oficial transmitido de um grupo a outro no formato diplomático da época. Por exemplo, IMagnMai 91d termina em suas linhas 8–10 com construção gramatical semelhante: <span class=\"greek\">εὖ</span> <span class=\"greek\">οὖν</span> <span class=\"greek\">ποιήσετε</span> [<span class=\"greek\">τ</span>]<span class=\"greek\">ὸν</span> [<span class=\"greek\">ἔπαινον</span>|<span class=\"greek\">Σωσικλείου</span>]<span class=\"greek\">ς</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">τὰς</span> <span class=\"greek\">δεδομένας</span> <span class=\"greek\">αὐτῷ</span> <span class=\"greek\">τιμὰς</span> <span class=\"greek\">εὐνόως</span> <span class=\"greek\">ἀποδεξά</span>[<span class=\"greek\">μενοι</span> <span class=\"greek\">ἔρρω</span>|<span class=\"greek\">σθε</span>], «agireis bem ao receber favoravelmente o elogio a Sósicles e as honras que lhe foram concedidas. Passai bem». Assim, <span class=\"greek\">εὖ</span> <span class=\"greek\">πράσσειν</span> exprime característica fundamental do sistema de reciprocidade da sociedade greco-romana: quem recebe um benefício «age corretamente» ao retribuí-lo de alguma maneira. De modo semelhante, IEph 4:2 e ISm 11:3 pedem tradução como «agir corretamente». <span class=\"greek\">ἵνα</span> <span class=\"greek\">εὖ</span> <span class=\"greek\">σοι</span> <span class=\"greek\">γένηται</span>, «para que prosperes», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.6.3\" target=\"_blank\" rel=\"noopener noreferrer\">Ef 6:3</a>; cf. Êx 20:12; Dt 5:16; Gn 12:13; Dt 4:40; TestJob 46:9; ParJer 7:9. <span class=\"greek\">εὖ</span> <span class=\"greek\">ἔχειν</span> <span class=\"greek\">πρός</span> <span class=\"greek\">τινα</span>, «ter boa disposição ou benevolência para com alguém», Hs 9, 10, 7.</p><p class=\"entry-text\">② <strong>Conformidade com um padrão de desempenho: muito bem! excelente!</strong> Como interjeição absoluta (Ps.-Xenofonte, Cyneg. 6, 20 Rühl, variante), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.25.21\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 25:21</a>, 23; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.19.17\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 19:17</a>, variante (em lugar de <span class=\"greek\">εὖγε</span>). Bibliografia: DELG, s.v. <span class=\"greek\">ἐύ</span>; M-M.</p></section></article>\n<article id=\"entry-eua-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Εὕα, ας, ἡ</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦Heúa⟧</span><span class=\"separator\">·</span><span>nome próprio feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">Genitivo <span class=\"greek\">ας</span>; hebraico חַוָּה. Variante <span class=\"greek\">Εὔα</span> em Tischendorf, S. Vog.; Schmiedel prefere <span class=\"greek\">Ἕυα</span>. <strong>Eva</strong>: Gn 4:1; Tb 8:6; TestAbr A 8, p. 85, 26 [Stone p. 18]; ApcEsdr 2:16; ApcMos; SibOr 1, 29; Fílon, Leg. All. 2, 81; Josefo, Ant. 1, 49; Justino; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.2.13\" target=\"_blank\" rel=\"noopener noreferrer\">1Tm 2:13</a>. A sedução/engano de Eva pela serpente: <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.11.3\" target=\"_blank\" rel=\"noopener noreferrer\">2Co 11:3</a>; B 12:5; Dg 12:8; GJs 13:1; cf. Justino, D. 79, 4 e outros. Bibliografia: W. Staerk, «Eva-Maria», ZNW 33 (1934), 97–104; BHHW I 499.</p></section></article>\n<article id=\"entry-euangelizo-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐαγγελίζω</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦euangelízō⟧</span><span class=\"separator\">·</span><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\"><span class=\"greek\">εὐαγγελίζω</span>: ver o verbete seguinte. Futuro <span class=\"greek\">εὐαγγελιῶ</span> (2Rs 18:19); primeiro aoristo <span class=\"greek\">εὐηγγέλισα</span>. A voz ativa encontra-se na literatura aqui abrangida apenas em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.10.7\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 10:7</a>; 14:6; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.16.17\" target=\"_blank\" rel=\"noopener noreferrer\">At 16:17</a>, variante de leitura. Pertence ao grego posterior (Polieno 5, 7; Cássio Dião 61, 13, 4; PGiss 27, 6 [séc. II d.C.]; PAmh 2, 16; 1Rs 31:9; 2Rs 18:19s.; cf. Frínico 268 Lob.) e não difere em sentido (B-D-F §309, 1) da voz média, muito mais comum no grego anterior, <span class=\"greek\">εὐαγγελίζομαι</span> (Aristófanes, Demóstenes e outros; Fílon, Josefo; predominante na LXX; também PsSol 11:1; ParJer; Justino; no passivo, JosAs 19:2). Imperfeito médio <span class=\"greek\">εὐηγγελιζόμην</span>; futuro <span class=\"greek\">εὐαγγελιοῦμαι</span> (2Rs 18:20; Is 60:6); primeiro aoristo médio <span class=\"greek\">εὐηγγελισάμην</span> (sobre o aumento, B-D-F §69, 4; Robertson 367). Os seguintes tempos são empregados em sentido passivo: presente; primeiro aoristo <span class=\"greek\">εὐηγγελίσθην</span>; perfeito <span class=\"greek\">εὐηγγέλισμαι</span>.</p><p class=\"entry-text\">① <strong>Em geral: trazer boas notícias; anunciar notícias favoráveis.</strong> Com <span class=\"greek\">τί</span> <span class=\"greek\">τινι</span>, «anunciar alguma coisa a alguém» (Josefo, Bell. 3, 503; Ant. 7, 250), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.19\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 1:19</a>; <span class=\"greek\">ταῦτα</span> <span class=\"greek\">εὐ</span>., «anunciar estas coisas», como no anúncio angélico do nascimento iminente de um filho muito desejado (Josefo, Ant. 5, 282; cf. 277 <span class=\"greek\">εὐ</span>. <span class=\"greek\">αὐτῇ</span> <span class=\"greek\">παιδὸς</span> <span class=\"greek\">γονήν</span>; Justino, D. 56, 5 <span class=\"greek\">εὐ</span>. <span class=\"greek\">τῇ</span> <span class=\"greek\">Σάρρᾳ</span> <span class=\"greek\">ὅτι</span> <span class=\"greek\">τέκνον</span> <span class=\"greek\">ἕξει</span>); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.2.10\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 2:10</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.3.6\" target=\"_blank\" rel=\"noopener noreferrer\">1Ts 3:6</a>. Com <span class=\"greek\">τὶ</span> <span class=\"greek\">ἐπί</span> <span class=\"greek\">τινα</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.14.6\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 14:6</a>. Com <span class=\"greek\">τινά</span>, «a alguém»; cf. passivo com sujeito pessoal em JosAs 19:2 <span class=\"greek\">ἐγὼ</span> <span class=\"greek\">εὐηγγελίσθην</span> <span class=\"greek\">περὶ</span> <span class=\"greek\">σοῦ</span> <span class=\"greek\">ἐξ</span> <span class=\"greek\">οὐρανοῦ</span>; sobre a construção, ver ②: <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.10.7\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 10:7</a>.</p><p class=\"entry-text\">② <strong>Em sentido predominantemente específico: proclamar a mensagem divina de salvação; anunciar o evangelho; proclamar; pregar.</strong> Cf. Is 60:6; Sl 67:12; PsSol 11:1; ParJer 5:19 <span class=\"greek\">εὐαγγελίσασθαι</span> <span class=\"greek\">αὐτοῖς</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">καταχρῆσαι</span> <span class=\"greek\">αὐτοὺς</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">λόγον</span> e outros. Cf. ainda PGM 5, 142 <span class=\"greek\">εὐάγγελος</span> <span class=\"greek\">τ</span>. <span class=\"greek\">θεοῦ</span>, «mensageiro de boas notícias de Deus».</p><p class=\"entry-text\">ⓐ <strong>Voz média.</strong></p><p class=\"entry-text\">ⓐ <span class=\"greek\">α</span>. <strong>Mencionam-se tanto a mensagem anunciada quanto a pessoa que a recebe:</strong> <span class=\"greek\">τί</span> <span class=\"greek\">τινι</span>, «anunciar alguma coisa a alguém»: <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.4.43\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 4:43</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.8.35\" target=\"_blank\" rel=\"noopener noreferrer\">At 8:35</a> (<span class=\"greek\">τὸν</span> <span class=\"greek\">Ἰησοῦν</span>, «Jesus»); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.1.8\" target=\"_blank\" rel=\"noopener noreferrer\">Gl 1:8</a>b; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.2.17\" target=\"_blank\" rel=\"noopener noreferrer\">Ef 2:17</a>; 3:8; B 8:3; 14:9. <span class=\"greek\">τὸ</span> <span class=\"greek\">εὐαγγέλιον</span> <span class=\"greek\">εὐ</span>. <span class=\"greek\">τινι</span>, «anunciar o evangelho a alguém», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.15.1\" target=\"_blank\" rel=\"noopener noreferrer\">1Co 15:1</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.11.7\" target=\"_blank\" rel=\"noopener noreferrer\">2Co 11:7</a>. <span class=\"greek\">τί</span> <span class=\"greek\">τινα</span>, «anunciar alguma coisa a alguém» (sobre a construção, ver abaixo), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.13.32\" target=\"_blank\" rel=\"noopener noreferrer\">At 13:32</a>. <span class=\"greek\">εὐ</span>. <span class=\"greek\">τὸν</span> <span class=\"greek\">υἱὸν</span> <span class=\"greek\">τ</span>. <span class=\"greek\">θεοῦ</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τ</span>. <span class=\"greek\">ἔθνεσιν</span>, «proclamar o Filho de Deus entre as nações», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.1.16\" target=\"_blank\" rel=\"noopener noreferrer\">Gl 1:16</a>.</p><p class=\"entry-text\">ⓐ <span class=\"greek\">β</span>. <strong>Menciona-se o objeto da proclamação:</strong> <span class=\"greek\">τὶ</span>, «algo»; cf. Luciano, Tyrannic. 9 <span class=\"greek\">τὴν</span> <span class=\"greek\">ἐλευθερίαν</span>, «a liberdade»; Sinésio, Prov. 1, 7, p. 96a, [os <span class=\"greek\">σημεῖα</span> celestes] <span class=\"greek\">τὴν</span> <span class=\"greek\">βασιλείαν</span> <span class=\"greek\">Αἰγυπτίοις</span> <span class=\"greek\">εὐηγγελίζετο</span> [voz média], «anunciou aos egípcios o reinado favorável»; Sl 39:10; 95:2. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.8.1\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 8:1</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.8.4\" target=\"_blank\" rel=\"noopener noreferrer\">At 8:4</a>; 10:36; 15:35; 17:18; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.10.15\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 10:15</a> (Is 52:7); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.1.23\" target=\"_blank\" rel=\"noopener noreferrer\">Gl 1:23</a>. O objeto da proclamação pode também ser uma <strong>pessoa em acusativo</strong>, <span class=\"greek\">τινά</span>: <span class=\"greek\">τ</span>. <span class=\"greek\">Χριστὸν</span> <span class=\"greek\">Ἰ</span>., «Jesus Cristo», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.5.42\" target=\"_blank\" rel=\"noopener noreferrer\">At 5:42</a>; <span class=\"greek\">τ</span>. <span class=\"greek\">κύριον</span> <span class=\"greek\">Ἰ</span>., «o Senhor Jesus», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.11.20\" target=\"_blank\" rel=\"noopener noreferrer\">At 11:20</a>; cf. 17:18. <span class=\"greek\">εὐ</span>. <span class=\"greek\">περὶ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">βασιλείας</span>, «proclamar acerca do reino», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.8.12\" target=\"_blank\" rel=\"noopener noreferrer\">At 8:12</a>; cf. Josefo, Ant. 15, 209 <span class=\"greek\">περὶ</span> <span class=\"greek\">τούτων</span> <span class=\"greek\">εὐηγγελίζετο</span>. Com acusativo seguido de infinitivo (Plutarco, Mar. 22 [22, 4]; Josefo, Ant. 6, 56): <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.14.15\" target=\"_blank\" rel=\"noopener noreferrer\">At 14:15</a>; 1Cl 42:3.</p><p class=\"entry-text\">ⓐ <span class=\"greek\">γ</span>. <strong>Menciona-se o destinatário da mensagem:</strong> <span class=\"greek\">τινί</span>, «a alguém» (Aristófanes, Eq. 643 e outros; Jr 20:15; ParJer 3:15; Fílon, De Jos. 250; Josefo, Ant. 5, 24): <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.4.18\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 4:18</a> (Is 61:1); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.1.15\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 1:15</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.15.2\" target=\"_blank\" rel=\"noopener noreferrer\">1Co 15:2</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.1.8\" target=\"_blank\" rel=\"noopener noreferrer\">Gl 1:8</a>a; 4:13; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.1.12\" target=\"_blank\" rel=\"noopener noreferrer\">1Pe 1:12</a>, P72. <span class=\"greek\">εἰς</span> <span class=\"greek\">τ</span>. <span class=\"greek\">ὑπερέκεινα</span> <span class=\"greek\">ὑμῶν</span> <span class=\"greek\">εὐ</span>., «anunciar o evangelho em terras além de vós», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.10.16\" target=\"_blank\" rel=\"noopener noreferrer\">2Co 10:16</a>; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.1.25\" target=\"_blank\" rel=\"noopener noreferrer\">1Pe 1:25</a>. Com acusativo <span class=\"greek\">τινά</span>, «alguém» (Alcífron 2, 9, 2, variante; Heliodoro 2, 10, 1, ed. I. Bekker [conforme manuscritos]; Josefo, Ant. 18, 228; Eusébio, HE 3, 4): <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.28\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 1:28</a>, variante; 3:18; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.8.25\" target=\"_blank\" rel=\"noopener noreferrer\">At 8:25</a>, 40; 14:21; 16:10; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.1.9\" target=\"_blank\" rel=\"noopener noreferrer\">Gl 1:9</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.1.12\" target=\"_blank\" rel=\"noopener noreferrer\">1Pe 1:12</a>; Pol 6:3; PtK 3, p. 15, 19.</p><p class=\"entry-text\">ⓐ <span class=\"greek\">δ</span>. <strong>Uso absoluto, sem objeto expresso: proclamar; pregar</strong> (ParJer 9:20 <span class=\"greek\">ἀποστόλους</span> <span class=\"greek\">ἵνα</span> <span class=\"greek\">εὐαγγελίζονται</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τοῖς</span> <span class=\"greek\">ἔθνεσιν</span>): <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.9.6\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 9:6</a>; 20:1; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.14.7\" target=\"_blank\" rel=\"noopener noreferrer\">At 14:7</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.15.20\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 15:20</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.1.17\" target=\"_blank\" rel=\"noopener noreferrer\">1Co 1:17</a>; 9:16, 18.</p><p class=\"entry-text\">ⓑ <strong>Voz passiva.</strong></p><p class=\"entry-text\">ⓑ <span class=\"greek\">α</span>. <strong>Com coisa como sujeito: ser proclamado.</strong> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.16.16\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 16:16</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.1.11\" target=\"_blank\" rel=\"noopener noreferrer\">Gl 1:11</a> (<span class=\"greek\">τὸ</span> <span class=\"greek\">εὐαγγέλιον</span>, «o evangelho»); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.1.25\" target=\"_blank\" rel=\"noopener noreferrer\">1Pe 1:25</a>. Impessoal: <span class=\"greek\">νεκροῖς</span> <span class=\"greek\">εὐηγγελίσθη</span>, «foi anunciado [o evangelho] aos mortos», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.4.6\" target=\"_blank\" rel=\"noopener noreferrer\">1Pe 4:6</a>; cf. Justino, D. 72, 4.</p><p class=\"entry-text\">ⓑ <span class=\"greek\">β</span>. <strong>Com pessoa como sujeito, a que recebe a mensagem de libertação: receber o anúncio de boas notícias</strong> (2Rs 18:31; Jl 3:5); do evangelho, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.11.5\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 11:5</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.7.22\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 7:22</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.4.2\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 4:2</a>, 6. Sobre apóstolos que recebem o evangelho em benefício de outros, com <span class=\"greek\">ἀπό</span> <span class=\"greek\">τινος</span>, «de alguém»: 1Cl 42:1. Bibliografia: B. 1478; DELG, s.v. <span class=\"greek\">ἄγγελος</span>; M-M; EDNT; TW; Spicq.</p></section></article>\n"};
